class FileError : public std::runtime_error {
    public:
    FileError() : std::runtime_error("File Issue") {}
};

// BAD PRACTICE: Throwing by pointer (dereferenced).
// Requires dynamic allocation (new) and risks memory leaks
// if the exception is caught by value.
FileError* p = new FileError();
// throw *p;

// BEST PRACTICE: Throw by value.
// Ensures the standard mechanism handles safe copy/move
// and guarantees destruction cleanup.
throw FileError();
